#include "libaxiom.h"
int main(void){char line[128];size_t length=0;ax_puts("AXIOM USER SHELL (RING 3)\nYOUR SYSTEM. YOUR RULES.\nTYPE HELP FOR COMMANDS.\n\naxiom> ");for(;;){long value=ax_key_poll();if(value<=0){ax_sleep(1);continue;}char c=(char)value;if(c=='\n'){ax_puts("\n");line[length]=0;if(ax_streq(line,"exit")){ax_puts("LEAVING USER SHELL FOR RECOVERY CONSOLE.\n");return 0;}if(length)ax_command(line);length=0;ax_puts("axiom> ");continue;}if(c=='\b'){if(length){length--;ax_write("\b",1);}continue;}if(c>=32&&c<127&&length+1<sizeof(line)){line[length++]=c;ax_write(&c,1);}}}
